using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Mewgic;
public static class Part12DEditor {
 public static void Models(){Directory.CreateDirectory("docs/ProductionReports/Part12D");Part12CLocalization.Validate();GameplayBoosterTests.ModelTests();Part12DModelTests.Run();}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Play Mode durdurulmalı");Part12CEditor.DiskCheck();SessionState.SetString("Part12D.Key","Mewgic.Tests.Part12D."+Guid.NewGuid().ToString("N"));SessionState.SetString("Part12D.Archive",Path.Combine(Path.GetTempPath(),"Mewgic-Part12D-"+Guid.NewGuid().ToString("N")));EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity");new GameObject("PART12D QA").AddComponent<Part12DProbe>();Part12BEditor.Size(1600);EditorApplication.isPlaying=true;}
 public static void Reload(){EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity");new GameObject("PART12D Reload QA").AddComponent<Part12DProbe>().reload=true;Part12BEditor.Size(1600);EditorApplication.isPlaying=true;}
 public static void Preview(){SessionState.SetString("Part12D.Key","Mewgic.Tests.Part12D.Preview");EditorSceneManager.OpenScene("Assets/Scenes/Gameplay.unity");new GameObject("PART12D Safe Preview").AddComponent<Part12DProbe>().preview=true;Part12BEditor.Size(1600);EditorApplication.isPlaying=true;}
public static void ProfileVariants(){var pool=Newtonsoft.Json.JsonConvert.DeserializeObject<Mewgic.Core.GeneratedLevel[]>(Resources.Load<TextAsset>("Levels/GeneratedFallbacks").text);var r=Mewgic.Core.WorldMapRules.Request(20);var a=Mewgic.Core.LevelGenerator.Resolve(r,Array.Empty<string>(),pool).level;var b=Mewgic.Core.LevelGenerator.Resolve(r,new[]{a.signature},pool).level;a.Validate();b.Validate();File.WriteAllText("docs/ProductionReports/Part12D/PROFILE_VARIANTS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{sameLevel=20,firstSeed=a.seed,secondSeed=b.seed,historyCanChangeCandidate=a.signature!=b.signature,firstVerified=true,secondVerified=true},Newtonsoft.Json.Formatting.Indented));}
}
